#nullable enable

using System;
using System.Linq;
using Haitch.Roslyn.Diagnostics;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Haitch.Roslyn.Models;

internal sealed record SyntaxInfo(bool IsPartial, bool AreContainingTypesPartial, LocationInfo? Location)
{
    public static SyntaxInfo From(TypeDeclarationSyntax typeDeclaration)
    {
        var isPartial = typeDeclaration.Modifiers.Any(SyntaxKind.PartialKeyword);
        var areContainingTypesPartial = AreAllPartial(typeDeclaration.Parent as TypeDeclarationSyntax);
        LocationInfo? location = LocationInfo.From(typeDeclaration.Identifier.GetLocation());

        return new SyntaxInfo(isPartial, areContainingTypesPartial, location);
    }

    /// <summary>
    /// Describes a type, method, property or field declarator. <see cref="IsPartial"/> is the member's own
    /// <c>partial</c> modifier (never set for a field), <see cref="AreContainingTypesPartial"/> covers the
    /// whole containing-type chain, and <see cref="Location"/> is the member's identifier. A field is passed
    /// as its <see cref="VariableDeclaratorSyntax"/> because one declaration can declare several fields;
    /// a declarator that does not belong to a field (a local, for example) throws <see cref="ArgumentException"/>.
    /// </summary>
    public static SyntaxInfo From(SyntaxNode member)
    {
        if (member is TypeDeclarationSyntax typeDeclaration)
        {
            return From(typeDeclaration);
        }

        var (isPartial, identifier) = member switch
        {
            MethodDeclarationSyntax method => (method.Modifiers.Any(SyntaxKind.PartialKeyword), method.Identifier),
            PropertyDeclarationSyntax property => (
                property.Modifiers.Any(SyntaxKind.PartialKeyword),
                property.Identifier
            ),
            VariableDeclaratorSyntax { Parent.Parent: FieldDeclarationSyntax } variable => (
                false,
                variable.Identifier
            ),
            _ => throw new ArgumentException(
                $"Unsupported member syntax {member.Kind()}.",
                nameof(member)
            ),
        };

        var containingType = member.Ancestors().OfType<TypeDeclarationSyntax>().FirstOrDefault();
        LocationInfo? location = LocationInfo.From(identifier.GetLocation());

        return new SyntaxInfo(isPartial, AreAllPartial(containingType), location);
    }

    private static bool AreAllPartial(TypeDeclarationSyntax? innermost)
    {
        SyntaxNode? current = innermost;

        while (current is TypeDeclarationSyntax type)
        {
            if (!type.Modifiers.Any(SyntaxKind.PartialKeyword))
            {
                return false;
            }

            current = type.Parent;
        }

        return true;
    }
}
